#[derive(Debug)] pub struct FfmpegStream { pub(crate) ffmpeg_path: std::path::PathBuf, pub(crate) file_path: String, pub(crate) sample_rate: u32, pub(crate) channels: u16, pub(crate) duration_ms: i64, pub(crate) cancel: Arc<CancelHandle>, pub(crate) rx: crossbeam_channel::Receiver<Vec<f32>>, buffer: Vec<f32>, pos: usize, pub(crate) _stdout_thread: Option<thread::JoinHandle<()>>, _stderr_thread: Option<thread::JoinHandle<()>>, } impl Clone for FfmpegStream { fn clone(&self) -> Self { Self { ffmpeg_path: self.ffmpeg_path.clone(), file_path: self.file_path.clone(), sample_rate: self.sample_rate, channels: self.channels, duration_ms: self.duration_ms, cancel: self.cancel.clone(), rx: self.rx.clone(), buffer: Vec::new(), pos: 0, _stdout_thread: None, _stderr_thread: None } } } impl FfmpegStream { pub fn new(ffmpeg_path: &Path, file_path: &str, sample_rate: u32, channels: u16, duration_ms: i64) -> Result<Self, String> { let ffprobe_path = locate("ffprobe.exe").map(|(p, _, _)| p).ok_or("找不到 ffprobe")?; let value = crate::audio_decode::ffprobe_json(&ffprobe_path, file_path)?; let streams = value["streams"].as_array().ok_or("無音訊串流")?; let audio_stream = streams.iter().find(|s| s["codec_type"] == "audio").ok_or("無音訊串流")?; let codec = audio_stream["codec_name"].as_str().unwrap_or(""); let sr = audio_stream["sample_rate"].as_str().unwrap_or("0").parse().unwrap_or(sample_rate); let ch = audio_stream["channels"].as_u64().unwrap_or(0) as u16; let dur = value["format"]["duration"].as_str().and_then(|d| d.parse::<f64>().ok()); let dur_ms = dur.map(|d| (d * 1000.0) as i64).unwrap_or(duration_ms); let (final_sr, final_ch) = if codec.starts_with("dsd") { let dsd_rate = sr; let pcm_rate = (dsd_rate / 32).min(176400); (pcm_rate, 2) } else { (sr.max(1), ch.max(1)) }; let cancel = Arc::new(CancelHandle::new(Duration::from_secs(10))); let (tx, rx) = crossbeam_channel::bounded(128); let file_path_owned = file_path.to_string(); let ffmpeg_path_owned = ffmpeg_path.to_path_buf(); let cancel_stdout = cancel.clone(); let cancel_stderr = cancel.clone(); let stdout_thread = thread::spawn(move || { let mut child = match Command::new(&ffmpeg_path_owned).args(["-nostdin", "-v", "error", "-protocol_whitelist", "file,pipe", "-ss", "0", "-i", &file_path_owned, "-map", "0:a:0", "-f", "f32le", "-ac", &final_ch.to_string(), "-ar", &final_sr.to_string(), "-"]).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn() { Ok(c) => c, Err(e) => { eprintln("ffmpeg spawn failed: {e}"); return; } }; let mut stdout = match child.stdout.take() { Some(o) => o, None => return }; let mut stderr = child.stderr.take(); cancel_stdout.set_child(child); let stderr_thread = thread::spawn(move || { use std::io::Read; let mut buf = vec![0u8; 4096]; let mut sanitizer = crate::open_with::Sanitizer::new(); if let Some(mut stderr) = stderr { loop { if cancel_stderr.is_cancelled() { break; } match stderr.read(&mut buf) { Ok(0) => break, Ok(n) => { let chunk_text = String::from_utf8_lossy(&buf[..n]); sanitizer.sanitize_chunk(&chunk_text); } Err(_) => break, } } } let cleaned = sanitizer.finish(); if !cleaned.is_empty() { crate::open_with::log_line_raw(&cleaned); } }); const CHUNK_SAMPLES: usize = 4096; let mut chunk = Vec::with_capacity(CHUNK_SAMPLES * 4); let mut buf = [0u8; 8192]; loop { if cancel_stdout.is_cancelled() { break; } match stdout.read(&mut buf) { Ok(0) => break, Ok(n) => { chunk.extend_from_slice(&buf[..n]); while chunk.len() >= CHUNK_SAMPLES * 4 { let chunk_bytes: Vec<u8> = chunk.drain(..CHUNK_SAMPLES * 4).collect(); let samples: Vec<f32> = chunk_bytes.chunks_exact(4).map(|c| f32::from_le_bytes([c[0],c[1],c[2],c[3]])).collect(); loop { if cancel_stdout.is_cancelled() { break; } match tx.try_send(samples.clone()) { Ok(()) => break, Err(crossbeam_channel::TrySendError::Full(_)) => { thread::sleep(Duration::from_millis(5)); continue; } Err(crossbeam_channel::TrySendError::Disconnected(_)) => break, } } } } Err(_) => break, } } let _ = tx.send(Vec::new()); let _ = stderr_thread.join(); }); Ok(Self { ffmpeg_path: ffmpeg_path.to_path_buf(), file_path: file_path.to_string(), sample_rate: final_sr, channels: final_ch, duration_ms: dur_ms, cancel, rx, buffer: Vec::new(), pos: 0, _stdout_thread: Some(stdout_thread), _stderr_thread: None }) } pub fn open_with_seek(&self, start_ms: i64) -> Result<Box<dyn Iterator<Item = f32> + Send>, String> { let ffmpeg_path = self.ffmpeg_path.clone(); let file_path = self.file_path.clone(); let channels = self.channels as usize; let sample_rate = self.sample_rate.max(1); let cancel = self.cancel.clone(); let (tx, rx) = crossbeam_channel::bounded(128); thread::spawn(move || { let Ok(mut child) = Command::new(&ffmpeg_path).args(["-nostdin", "-v", "error", "-protocol_whitelist", "file,pipe", "-ss", &format!("{:.3}", start_ms as f64 / 1000.0), "-i", &file_path, "-map", "0:a:0", "-f", "f32le", "-ac", &channels.to_string(), "-ar", &sample_rate.to_string(), "-"]).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn() else { let _ = tx.send(Vec::new()); return; }; let mut stdout = match child.stdout.take() { Some(o) => o, None => { let _ = tx.send(Vec::new()); return; } }; let mut stderr = child.stderr.take(); let cancel_stderr = cancel.clone(); thread::spawn(move || { use std::io::Read; let mut buf = vec![0u8; 4096]; let mut sanitizer = crate::open_with::Sanitizer::new(); if let Some(mut stderr) = stderr { loop { if cancel_stderr.is_cancelled() { break; } match stderr.read(&mut buf) { Ok(0) => break, Ok(n) => { let chunk_text = String::from_utf8_lossy(&buf[..n]); sanitizer.sanitize_chunk(&chunk_text); } Err(_) => break, } } } let cleaned = sanitizer.finish(); if !cleaned.is_empty() { crate::open_with::log_line_raw(&cleaned); } }); cancel.set_child(child); let mut buf = [0u8; 8192]; let mut chunk = Vec::with_capacity(4096 * 4); loop { if cancel.is_cancelled() { break; } match stdout.read(&mut buf) { Ok(0) => break, Ok(n) => { chunk.extend_from_slice(&buf[..n]); while chunk.len() >= 4096 * 4 { let chunk_bytes: Vec<u8> = chunk.drain(..4096 * 4).collect(); let samples: Vec<f32> = chunk_bytes.chunks_exact(4).map(|c| f32::from_le_bytes([c[0],c[1],c[2],c[3]])).collect(); if tx.send(samples).is_err() { return; } } } Err(_) => break, } } let _ = tx.send(Vec::new()); }); Ok(Box::new(SeekIter { rx, buffer: Vec::new(), pos: 0 })) } pub fn sample_rate(&self) -> u32 { self.sample_rate } pub fn channels(&self) -> u16 { self.channels } pub fn duration_ms(&self) -> Option<i64> { if self.duration_ms > 0 { Some(self.duration_ms) } else { None } } pub fn cancel(&self) { self.cancel.cancel(); } } impl Drop for FfmpegStream { fn drop(&mut self) { self.cancel.cancel(); } } impl Iterator for FfmpegStream { type Item = f32; fn next(&mut self) -> Option<f32> { loop { if self.pos < self.buffer.len() { let s = self.buffer[self.pos]; self.pos += 1; return Some(s); } match self.rx.recv_timeout(Duration::from_millis(100)) { Ok(chunk) => { if chunk.is_empty() { return None; } self.buffer = chunk; self.pos = 0; } Err(_) => return None, } } } } struct SeekIter { rx: crossbeam_channel::Receiver<Vec<f32>>, buffer: Vec<f32>, pos: usize } impl Iterator for SeekIter { type Item = f32; fn next(&mut self) -> Option<f32> { loop { if self.pos < self.buffer.len() { let s = self.buffer[self.pos]; self.pos += 1; return Some(s); } match self.rx.try_recv() { Ok(chunk) => { if chunk.is_empty() { return None; } self.buffer = chunk; self.pos = 0; } Err(crossbeam_channel::TryRecvError::Empty) => { return Some(0.0); } Err(_) => return None, } } } } impl Source for FfmpegStream { fn current_frame_len(&self) -> Option<usize> { None } fn channels(&self) -> u16 { self.channels } fn sample_rate(&self) -> u32 { self.sample_rate } fn total_duration(&self) -> Option<Duration> { self.duration_ms().map(|ms| Duration::from_millis(ms.max(0) as u64)) } }""")
